var rf151SaveHistory = async function rf151SaveHistory(refreshHealth){
 try{
  const ed=rf151Edit();if(!ed)throw Error('Nincs szerkesztett edzés.');
  const i=rf142FindHistoryIndex(ed.key);if(i<0)throw Error('Az edzés nem található.');
  const started=rf142IsoFromLocal($('#rf151Start')?.value),finished=rf142IsoFromLocal($('#rf151End')?.value);rf142ValidWindow(started,finished);
  if(!ed.workout.exercises.length)throw Error('Az edzésben legalább 1 gyakorlatnak maradnia kell.');
  for(const e of ed.workout.exercises){if(!(e.sets||[]).length)throw Error('Minden gyakorlatnál legalább 1 sorozat szükséges.');rf151Renumber(e);}
  const h=history(),old=h[i];h[i]={...ed.workout,started,finished,editedAt:new Date().toISOString()};h.sort((a,b)=>String(b.started||'').localeCompare(String(a.started||'')));db.set('history',h);
  if(state.feedbackStarted===old.started)state.feedbackStarted=started;
  if(state.health){if(state.health.workout===old.started)state.health.workout=started;state.health.summary=null;}
  state.rf151HistoryEdit=null;
  const saved=h.find(x=>x.started===started&&x.finished===finished);
  if(refreshHealth){await rf142ReadHealthForWorkout(saved);return;}
  alert('Az edzés módosításai mentve.');go('history');
 }catch(e){alert(e.message||'Az edzés mentése nem sikerült.');}
};
