var rf153MigratePlan = function rf153MigratePlan(){
 if(db.get('rf153PlanMigrated',false))return;
 const p=plan();let changed=false;
 for(const w of ['A','B'])p[w]=(p[w]||[]).map(id=>{if(id==='dead-bug'){changed=true;return 'crunch';}return id;});
 if(changed)db.set('plan',p);
 db.set('rf153PlanMigrated',true);
};
var rf153Move = function rf153Move(w,i,d){
 const p=plan(),a=p[w]||[],j=i+d;if(i<0||j<0||i>=a.length||j>=a.length)return;
 [a[i],a[j]]=[a[j],a[i]];db.set('plan',p);editPlan(w);
};
var rf153Remove = function rf153Remove(w,i){
 const p=plan(),a=p[w]||[];if(a.length<=1){alert('A programban legalább 1 gyakorlatnak maradnia kell.');return;}
 a.splice(i,1);db.set('plan',p);editPlan(w);
};
var rf153Add = function rf153Add(w){
 const id=$('#rf153AddExercise')?.value;if(!id)return;
 const p=plan(),a=p[w]||[];if(a.includes(id)){alert('Ez a gyakorlat már szerepel ebben a programban.');return;}
 a.push(id);db.set('plan',p);editPlan(w);
};
var rf153ResetDay = function rf153ResetDay(w){
 if(!confirm(`Visszaállítod a Full Body ${w} gyári programját?`))return;
 const p=plan();p[w]=DEFAULT_PLAN[w].map(id=>id==='dead-bug'?'crunch':id);db.set('plan',p);editPlan(w);
};
