editPlan=function(w){
 const p=plan(),exs=exercises(),a=p[w]||[];
 render(shell(`<main><button class="btn secondary" onclick="go('plan')">← Vissza</button><div class="section">Full Body ${w} szerkesztése</div>
 <div class="card"><strong>Program felépítése</strong><p class="small muted">Gyakorlatot cserélhetsz, hozzáadhatsz, törölhetsz és átrendezhetsz. A módosítások automatikusan mentődnek.</p></div>
 ${a.map((id,i)=>{const e=byId(id);return `<div class="setting">
   <div style="display:flex;gap:8px;align-items:center;justify-content:space-between"><strong>${i+1}. ${esc(e.hu)}</strong><div><button class="btn secondary" onclick="rf153Move('${w}',${i},-1)" ${i===0?'disabled':''}>↑</button> <button class="btn secondary" onclick="rf153Move('${w}',${i},1)" ${i===a.length-1?'disabled':''}>↓</button> <button class="btn secondary" onclick="rf153Remove('${w}',${i})">Törlés</button></div></div>
   <label>Gyakorlat cseréje</label><select class="field" onchange="changePlan('${w}',${i},this.value)">${exs.map(x=>`<option value="${x.id}" ${x.id===id?'selected':''}>${esc(x.hu)} — ${esc(x.en)}</option>`).join('')}</select>
   <label>Célismétlés / időtartam</label><input class="field" value="${esc(e.reps)}" onchange="changeExerciseValue('${id}','reps',this.value)">
   <label>Terhelés értelmezése</label><select class="field" onchange="changeExerciseValue('${id}','loadType',this.value);editPlan('${w}')">${['per_hand','total','single_dumbbell','bodyweight'].map(t=>`<option value="${t}" ${e.loadType===t?'selected':''}>${loadLabel(t)}</option>`).join('')}</select>
   ${e.loadType!=='bodyweight'?`<label>Induló súly (${loadLabel(e.loadType)})</label><input class="field" inputmode="decimal" value="${e.weight}" onchange="changeExerciseValue('${id}','weight',this.value)">`:''}
   <label>Sorozatok száma</label><select class="field" onchange="changeExerciseSets('${id}',this.value);editPlan('${w}')">${Array.from({length:10},(_,n)=>n+1).map(n=>`<option value="${n}" ${Number(e.sets)===n?'selected':''}>${n} sorozat</option>`).join('')}</select>
 </div>`}).join('')}
 <div class="card"><strong>Gyakorlat hozzáadása</strong><select class="field" id="rf153AddExercise"><option value="">Válassz gyakorlatot…</option>${exs.filter(e=>!a.includes(e.id)).map(e=>`<option value="${e.id}">${esc(e.hu)} — ${esc(e.en)}</option>`).join('')}</select><br><br><button class="btn secondary block" onclick="rf153Add('${w}')">+ Gyakorlat hozzáadása</button></div>
 <button class="btn secondary block" onclick="rf153ResetDay('${w}')">Full Body ${w} gyári visszaállítása</button><br><button class="btn block" onclick="go('plan')">Kész</button></main>`));
};

