var rf155ProgramState = function rf155ProgramState(){
 const ps=programs(),pid=activeProgramId(),pi=ps.findIndex(p=>p.id===pid);
 return {ps,pid,pi,program:pi>=0?ps[pi]:null};
};
var rf155DayState = function rf155DayState(dayId){
 const s=rf155ProgramState();
 const di=s.program?.days?.findIndex(d=>d.id===dayId)??-1;
 return {...s,di,day:di>=0?s.program.days[di]:null};
};
var rf155SaveDay = function rf155SaveDay(dayId,mutate){
 const s=rf155DayState(dayId);if(!s.program||!s.day)throw Error('Az aktív program vagy edzésnap nem található.');
 mutate(s.day,s.program);
 db.set('programs',s.ps);
 return s.day;
};
