const RF155_VERSION='1.5.5';


rf154Replace=function(w,i){
 try{
  const id=$('#rf154Replacement')?.value;if(!id)return;
  rf155SaveDay(w,(day)=>{
   const a=day.exercises||[];if(!a[i])throw Error('A kiválasztott gyakorlat nem található.');
   if(a.includes(id)&&a[i]!==id)throw Error('Ez a gyakorlat már szerepel ebben a programban.');
   a[i]=id;
  });
  showWorkout(w);
 }catch(e){alert(e.message||'A csere nem sikerült.');}
};

rf154Remove=function(w,i){
 try{
  const s=rf155DayState(w),a=s.day?.exercises||[];
  if(a.length<=1){alert('A programban legalább 1 gyakorlatnak maradnia kell.');return;}
  if(!confirm('Törlöd ezt a gyakorlatot a programból?'))return;
  rf155SaveDay(w,(day)=>{if(!day.exercises?.[i])throw Error('A kiválasztott gyakorlat nem található.');day.exercises.splice(i,1);});
  showWorkout(w);
 }catch(e){alert(e.message||'A törlés nem sikerült.');}
};

