var rf206LatestWeight = function rf206LatestWeight(){const w=weights();return w.length?Number(w[0].kg):null;};
var rf206WorkoutMinutes = function rf206WorkoutMinutes(h){const a=Date.parse(h?.started),b=Date.parse(h?.finished);return Number.isFinite(a)&&Number.isFinite(b)&&b>a?(b-a)/60000:0;};
var rf206EffortScore = function rf206EffortScore(h){const xs=(h?.exercises||[]).map(e=>e.effort).filter(Boolean),m={easy:0.82,good:1,hard:1.18,pain:0.9};return xs.length?xs.reduce((a,x)=>a+(m[x]||1),0)/xs.length:1;};
var rf206VolumeScore = function rf206VolumeScore(h){let v=0,n=0;for(const e of h?.exercises||[])for(const s of e.sets||[]){if(!s.done)continue;n++;v+=(Number(s.reps)||0)*(Number(s.weight)||0);}return n?Math.max(0.92,Math.min(1.08,1+(Math.log10(Math.max(1,v))-3)*0.035)):1;};
var rf206EstimatedKcal = function rf206EstimatedKcal(h,kg=rf206LatestWeight()){const min=rf206WorkoutMinutes(h);if(!Number.isFinite(kg)||kg<=0||min<=0)return null;const met=Math.max(3,Math.min(6.5,4.6*rf206EffortScore(h)*rf206VolumeScore(h)));return Math.round(met*3.5*kg/200*min);};
var rf206HealthTotals = function rf206HealthTotals(){const h=history(),kg=rf206LatestWeight();let kcal=0,count=0;for(const x of h){const k=rf206EstimatedKcal(x,kg);if(Number.isFinite(k)){kcal+=k;count++;}}return {kcal,count,last:h.length?rf206EstimatedKcal(h[0],kg):null};};
var rf206HealthHub = function rf206HealthHub(){state.tab='health';const latest=rf206LatestWeight(),t=rf206HealthTotals(),rec=state.health?.recovery;render(shell(`<main><div class="hero"><h1>Egészség</h1><div class="muted">Testsúly, edzésenergia és Health Connect adatok egy helyen.</div></div><div class="grid2"><div class="stat" role="button" onclick="state.tab='weight';render()"><small>Legutóbbi testsúly</small><strong>${latest==null?'—':latest+' kg'}</strong></div><div class="stat"><small>Legutóbbi edzés</small><strong>${t.last==null?'—':'≈ '+t.last+' kcal'}</strong></div></div><div class="card"><h2>Edzésenergia</h2><p class="small muted">Becslés az edzés időtartamából, testsúlyból, rögzített sorozatokból és nehézség-visszajelzésből.</p><div class="grid2"><div class="stat"><small>Becsült összesen</small><strong>${t.count?'≈ '+t.kcal+' kcal':'—'}</strong></div><div class="stat"><small>Becsült edzések</small><strong>${t.count}</strong></div></div></div><div class="card"><h2>Health Connect</h2><p class="small muted">${rec?'Alvás/HRV adatok beolvasva.':'A támogatott egészségadatokat a meglévő Health Connect kapcsolaton keresztül frissítheted.'}</p><button class="btn block" onclick="healthScreen()">Health Connect és regeneráció</button></div><div class="grid2"><button class="btn secondary" onclick="state.tab='weight';render()">Testsúly napló</button><button class="btn secondary" onclick="go('history')">Edzésnapló</button></div></main>`));};
