var rf207TodayRange = function rf207TodayRange(){
 const now=new Date(),start=new Date(now);start.setHours(0,0,0,0);
 return {start:start.toISOString(),end:now.toISOString()};
};
var rf207HealthDaily = function rf207HealthDaily(){return state.health?.daily||null;};
var rf207SourceLabel = function rf207SourceLabel(d){
 if(!d?.source)return 'Nincs kiválasztott adatforrás';
 return d.sourceLabels?.[d.source]||d.source;
};
var rf207PickSource = function rf207PickSource(d){
 const sources=Array.isArray(d?.sources)?d.sources:[];
 if(!sources.length)return '';
 const saved=state.health?.dailySource;
 if(saved&&sources.includes(saved))return saved;
 return sources.find(x=>/samsung/i.test((d.sourceLabels?.[x]||'')+' '+x))||sources[0];
};
var rf207ReadTodayHealth = async function rf207ReadTodayHealth(preferred=null){
 await healthAction(async p=>{
  state.health=state.health||{};
  const range=rf207TodayRange();
  let r=await p.readWorkout({...range,source:preferred||state.health.dailySource||''});
  let source=preferred||r.source||rf207PickSource(r);
  if(source&&r.source!==source)r=await p.readWorkout({...range,source});
  if(source)state.health.dailySource=source;
  state.health.daily={...r,source:source||r.source||'',readAt:new Date().toISOString()};
  return source?'Mai Health Connect adatok frissítve.':'Nem találtunk megosztott mai aktivitásadatot. Ellenőrizd a Health Connect adatforrásait és engedélyeit.';
 });
 // healthAction refreshes the current Health view; do not navigate after awaiting.
};
var rf207ChangeSource = function rf207ChangeSource(v){state.health=state.health||{};state.health.dailySource=v||'';rf207ReadTodayHealth(v||null);};
var rf207FmtNum = function rf207FmtNum(v,suffix=''){const n=Number(v);return Number.isFinite(n)?`${Math.round(n)}${suffix}`:'—';};
var rf207DailyCard = function rf207DailyCard(){
 const d=rf207HealthDaily();
 if(!d)return `<div class="card"><h2>Mai aktivitás • Health Connect</h2><p class="small muted">Aktív kalória és pulzusadatok a telefonon megosztott adatforrásból. Ezek nem kerülnek Google Drive mentésbe.</p><button class="btn block" onclick="rf207ReadTodayHealth()">Mai adatok beolvasása</button></div>`;
 const sources=Array.isArray(d.sources)?d.sources:[];
 const options=sources.length>1?`<label class="small">Adatforrás<select class="field" onchange="rf207ChangeSource(this.value)">${sources.map(x=>`<option value="${esc(x)}" ${x===d.source?'selected':''}>${esc(d.sourceLabels?.[x]||x)}</option>`).join('')}</select></label>`:'';
 return `<div class="card"><h2>Mai aktivitás • Health Connect</h2><p class="small muted">Forrás: ${esc(rf207SourceLabel(d))}${d.readAt?' • frissítve: '+esc(new Date(d.readAt).toLocaleTimeString('hu-HU',{hour:'2-digit',minute:'2-digit'})):''}</p>${options}<div class="grid2"><div class="stat"><small>Aktív energia</small><strong>${d.activeCalories==null?'—':rf207FmtNum(d.activeCalories,' kcal')}</strong></div><div class="stat"><small>Átlagpulzus</small><strong>${d.averageHeartRate==null?'—':rf207FmtNum(d.averageHeartRate,' bpm')}</strong></div><div class="stat"><small>Max. pulzus</small><strong>${d.maxHeartRate==null?'—':rf207FmtNum(d.maxHeartRate,' bpm')}</strong></div><div class="stat"><small>Pulzusminták</small><strong>${rf207FmtNum(d.heartRateSamples)}</strong></div></div><p class="small muted">A Health Connectből származó aktív energia mérési/forrásadata külön jelenik meg az app saját ≈ kcal becslésétől.</p><button class="btn secondary block" onclick="rf207ReadTodayHealth()">Mai adatok frissítése</button></div>`;
};
