var rf209ScheduleDone = function rf209ScheduleDone(x){return x?.status==='completed'||history().some(h=>h.scheduleId===x?.id);};
var rf209DeleteSchedule = function rf209DeleteSchedule(id){
 const s=scheduled(),i=s.findIndex(x=>x.id===id);if(i<0)return;
 const done=rf209ScheduleDone(s[i]);
 const msg=done?'Törlöd ezt a tervezett alkalmat? Az edzésnapló bejegyzése megmarad.':'Törlöd ezt a tervezett edzést?';
 tp2628Confirm(msg,{title:'Tervezett edzés törlése',confirmText:'Törlés',danger:true}).then(ok=>{if(!ok)return;const cur=scheduled(),j=cur.findIndex(x=>x.id===id);if(j<0)return;cur[j]={...cur[j],cancelled:true,status:'cancelled',updatedAt:Date.now()};db.set('scheduled',cur);render();});
};
var rf209NearestPlan = function rf209NearestPlan(dayId){
 const pid=activeProgramId(),now=Date.now(),limit=36*60*60*1000;
 return scheduled().filter(x=>!x.cancelled&&(x.status||'planned')==='planned'&&!history().some(h=>h.scheduleId===x.id)&&(x.programId||'home-basic')===pid&&(x.dayId||x.workout)===dayId)
  .map(x=>({x,d:Math.abs(Date.parse(x.start)-now)})).filter(v=>Number.isFinite(v.d)&&v.d<=limit).sort((a,b)=>a.d-b.d)[0]?.x||null;
};
/* RepForge 2.0.9: tervezett edzések feloldása, törlése és automatikus összerendelése. */
const RF209_VERSION='2.0.9';


// A naptárnapra koppintva a már létező alkalom bármilyen állapotban eltávolítható.
toggleCalendarDay=function(date){
 const items=scheduleOnDate(date).filter(x=>!x.cancelled);
 if(items.length){rf209DeleteSchedule(items[0].id);return;}
 const s=plannerSettings(),p=activeProgram(),idx=nextCycleIndex(p.id),item=makeScheduleItem(p,date,s.time,s.minutes,cycleDay(p,idx).id);
 addScheduleBatch([item]);render();
};

// A listában minden alkalom kap külön Törlés gombot, teljesített és kihagyott állapotban is.
scheduleListHtml=function(){
 const items=scheduled().filter(x=>!x.cancelled).sort((a,b)=>Date.parse(a.start)-Date.parse(b.start)).slice(-120);
 return items.length?items.map(x=>{
  const p=programById(x.programId||'home-basic'),d=programDay(p,x.dayId||x.workout),done=rf209ScheduleDone(x);
  return `<div class="card schedule-card"><div><strong>${esc(p?.name||'Program')} • ${esc(d?.name||x.dayId||x.workout)}</strong><div class="small muted">${esc(fmtDate(x.start))} • ${done?'Teljesítve':x.status==='skipped'?'Kihagyva':'Tervezett'}</div></div><div class="schedule-actions">${!done?`<button class="btn" onclick="startScheduledById('${x.id}')">Indítás</button>`:''}<button class="btn secondary" onclick="editSchedulePrompt('${x.id}')">Áthelyezés</button><button class="btn secondary" onclick="skipSchedule('${x.id}')">${x.status==='skipped'?'Vissza':'Kihagyás'}</button><button class="btn danger" onclick="rf209DeleteSchedule('${x.id}')">Törlés</button></div></div>`;
 }).join(''):'<div class="muted">Még nincs tervezett edzés.</div>';
};

// Ha ugyanazt a programnapot nem a tervezett kártyáról indítod, a közeli, még nyitott
// tervezett alkalmat automatikusan ehhez az edzéshez kapcsoljuk. Így más időpontban
// elvégzett edzés után nem marad bent tévesen "Tervezett" állapotban.

const rf209StartWorkout=startWorkout;
startWorkout=function(dayId,scheduleId=null,...rest){
 let sid=scheduleId;
 if(!sid){const candidate=rf209NearestPlan(dayId);if(candidate)sid=candidate.id;}
 return rf209StartWorkout(dayId,sid,...rest);
};

