var rf214Map = function rf214Map(html,map){let out=String(html);Object.keys(map).sort((a,b)=>b.length-a.length).forEach(k=>{out=out.split(k).join(map[k]);});return out;};
var rf214ExerciseCards = function rf214ExerciseCards(html,lang){if(lang==='hu')return html;return String(html).replace(/<div class="ex-name">([^<]*)<\/div><div class="en">([^<]+)<\/div>/g,(_m,hu,en)=>`<div class="ex-name">${lang==='en'?en:(RF214_MAPS[lang]?.[hu]||en)}</div>`).replace(/<h2>([^<]*)<\/h2><div class="en">([^<]+)<\/div>/g,(_m,hu,en)=>`<h2>${lang==='en'?en:(RF214_MAPS[lang]?.[hu]||en)}</h2>`);};
