var rf224DayChoice = function rf224DayChoice(date){
 const items=scheduleOnDate(date).filter(x=>!x.cancelled);
 if(items.length){rf209DeleteSchedule(items[0].id);return;}
 const p=activeProgram(),days=p?.days||[];if(!days.length)return;
 const t=rf224T(),labels=days.map((d,i)=>`${i+1}. ${d.name||d.id}`).join('\n');
 const raw=prompt(`${t.choose}\n\n${labels}`,'1');if(raw===null)return;
 const n=Number(raw),d=Number.isInteger(n)&&n>=1&&n<=days.length?days[n-1]:days.find(x=>String(x.id).toLowerCase()===String(raw).trim().toLowerCase());
 if(!d){alert(t.cancel);return;}
 const s=plannerSettings(),item=makeScheduleItem(p,date,s.time,s.minutes,d.id);addScheduleBatch([item]);render();
};
