const rf229RestoreText=restoreText;
restoreText=function(text){
  let rows=[];
  try{const parsed=JSON.parse(String(text).replace(/^\uFEFF/,''));if(Array.isArray(parsed?.recoveryHistory))rows=parsed.recoveryHistory.filter(x=>x&&typeof x.day==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x.day));}catch(_){}
  const ok=rf229RestoreText(text);
  if(ok&&rows.length){db.set('recoveryHistory',rows);rf229ApplyLatestRecovery();}
  return ok;
};
