 const scale=RF232_EFFORT_KEYS.map((k,i)=>`<button class="btn ${sel===k?'':'secondary'}" onclick="rf152SetEffort('${k}')"><span class="n">${i+1}</span><span class="lbl">${esc(t[k])}</span></button>`).join('');
