/* TrainPilot 2.4.2: tolerant Health Connect workout-session matching. */
const RF242_VERSION='2.4.2';
const RF242_TOLERANCE_MS=3*60*1000;


// Exact TrainPilot window first. If Samsung/Health Connect timestamps differ by seconds,
// discover the nearest Health exercise session inside a small tolerance window and re-read
// the metrics using that session's own exact timestamps. Only if this still yields nothing
// do we keep the small padded-window result as a last-resort attachment.
rf240SyncWorkout=async function(p,h,force=false){
  if(!rf240ValidWorkout(h))return false;const key=rf240WorkoutKey(h),old=h.health240;
  if(!force&&old?.windowStart===h.started&&old?.windowEnd===h.finished&&Date.now()-Date.parse(old.syncedAt||0)<6*3600000&&rf242HasTrainingMetric(old))return false;
  const exact=await p.readTrainingWindow({start:h.started,end:h.finished});
  if(rf242HasTrainingMetric(exact))return rf242SaveMatchedWorkoutHealth(key,h,exact,{matchMode:'exact',sourceWindowStart:h.started,sourceWindowEnd:h.finished});
  const start=new Date(Date.parse(h.started)-RF242_TOLERANCE_MS).toISOString(),end=new Date(Date.parse(h.finished)+RF242_TOLERANCE_MS).toISOString();
  const padded=await p.readTrainingWindow({start,end});const session=rf242BestSession(padded,h);
  if(session){
    try{
      const matched=await p.readTrainingWindow({start:session.start,end:session.end});
      if(rf242HasTrainingMetric(matched))return rf242SaveMatchedWorkoutHealth(key,h,matched,{matchMode:'exercise-session',sourceWindowStart:session.start,sourceWindowEnd:session.end,matchedExerciseSessionId:session.id||null,toleranceSeconds:RF242_TOLERANCE_MS/1000});
    }catch(_){}
  }
  return rf242SaveMatchedWorkoutHealth(key,h,padded,{matchMode:rf242HasTrainingMetric(padded)?'tolerance':'empty',sourceWindowStart:start,sourceWindowEnd:end,toleranceSeconds:RF242_TOLERANCE_MS/1000});
};


