  const names=[e?.hu,e?.en,tp149ExerciseName(e,'de'),tp149ExerciseName(e,'ro')];
  const equipment=['hu','en','de','ro'].map(function(lang){return tp149Equipment(e,lang);});
  const hay=normal(names.concat(equipment).join(' '));
