const TP149_DIALOG_LITERAL_KEYS={
 'Edzés elhagyása':'dialog.leaveWorkout.title',
 'Kilépsz a folyamatban lévő edzésből? A mentett vázlat megmarad, később folytathatod.':'dialog.leaveWorkout.message',
 'Kilépés':'dialog.leaveWorkout.action'
};
var tp149DialogLiteral=function tp149DialogLiteral(value){
 const raw=String(value??''),key=TP149_DIALOG_LITERAL_KEYS[raw];
 return key?tp149T(key):raw;
};

tp2628Confirm=function(message,opts={}){
 tp2628DialogRemove();
 return new Promise(function(resolve){
  const title=opts.title?tp149DialogLiteral(opts.title):tp149T('dialog.confirm.title'),confirmText=opts.confirmText?tp149DialogLiteral(opts.confirmText):tp149T('common.ok'),cancelText=opts.cancelText?tp149DialogLiteral(opts.cancelText):tp149T('common.cancel'),danger=opts.danger===true,body=tp149DialogLiteral(message);
  const modal=document.createElement('div');modal.id='tp2628Dialog';modal.className='tp2628-dialog-backdrop';
  modal.innerHTML='<div class="tp2628-dialog" role="dialog" aria-modal="true" aria-labelledby="tp2628DialogTitle"><h2 id="tp2628DialogTitle">'+tp2628DialogEscape(title)+'</h2><p class="tp2628-dialog-message">'+tp2628DialogEscape(body)+'</p><div class="tp2628-dialog-actions"><button type="button" class="btn secondary" data-tp2628-cancel>'+tp2628DialogEscape(cancelText)+'</button><button type="button" class="btn '+(danger?'danger':'')+'" data-tp2628-confirm>'+tp2628DialogEscape(confirmText)+'</button></div></div>';
  let finished=false;
  const finish=function(value){if(finished)return;finished=true;document.removeEventListener('keydown',key,true);modal.remove();resolve(value);};
  const key=function(e){if(e.key==='Escape'){e.preventDefault();finish(false);}};
  modal.querySelector('[data-tp2628-cancel]').onclick=function(){finish(false);};
  modal.querySelector('[data-tp2628-confirm]').onclick=function(){finish(true);};
  modal.addEventListener('click',function(e){if(e.target===modal)finish(false);});
  document.addEventListener('keydown',key,true);document.body.appendChild(modal);modal.querySelector('[data-tp2628-cancel]')?.focus();
 });
};
tp2628Notice=function(message,title='TrainPilot'){
 tp2628DialogRemove();
 return new Promise(function(resolve){
  const modal=document.createElement('div');modal.id='tp2628Dialog';modal.className='tp2628-dialog-backdrop';
  modal.innerHTML='<div class="tp2628-dialog" role="alertdialog" aria-modal="true" aria-labelledby="tp2628DialogTitle"><h2 id="tp2628DialogTitle">'+tp2628DialogEscape(title)+'</h2><p class="tp2628-dialog-message">'+tp2628DialogEscape(message)+'</p><div class="tp2628-dialog-actions single"><button type="button" class="btn" data-tp2628-ok>'+tp2628DialogEscape(tp149T('common.ok'))+'</button></div></div>';
  let finished=false;
  const finish=function(){if(finished)return;finished=true;document.removeEventListener('keydown',key,true);modal.remove();resolve(true);};
  const key=function(e){if(e.key==='Escape'||e.key==='Enter'){e.preventDefault();finish();}};
  modal.querySelector('[data-tp2628-ok]').onclick=finish;document.addEventListener('keydown',key,true);document.body.appendChild(modal);modal.querySelector('[data-tp2628-ok]')?.focus();
 });
};
tp2629Prompt=function(message,opts={}){
 tp2628DialogRemove();
 return new Promise(function(resolve){
  const title=opts.title||tp149T('dialog.input.title'),okText=opts.okText||tp149T('common.ok'),cancelText=opts.cancelText||tp149T('common.cancel');
  const modal=document.createElement('div');modal.id='tp2628Dialog';modal.className='tp2628-dialog-backdrop';
  modal.innerHTML='<div class="tp2628-dialog" role="dialog" aria-modal="true" aria-labelledby="tp2628DialogTitle"><h2 id="tp2628DialogTitle">'+tp2628DialogEscape(title)+'</h2><p class="tp2628-dialog-message">'+tp2628DialogEscape(message)+'</p><input class="field" data-tp2629-input type="'+tp2628DialogEscape(opts.type||'text')+'" value="'+tp2628DialogEscape(opts.value??'')+'" '+(opts.inputMode?'inputmode="'+tp2628DialogEscape(opts.inputMode)+'"':'')+'><div class="tp2628-dialog-actions" style="margin-top:14px"><button type="button" class="btn secondary" data-tp2628-cancel>'+tp2628DialogEscape(cancelText)+'</button><button type="button" class="btn" data-tp2628-confirm>'+tp2628DialogEscape(okText)+'</button></div></div>';
  let finished=false;const input=modal.querySelector('[data-tp2629-input]');
  const finish=function(value){if(finished)return;finished=true;document.removeEventListener('keydown',key,true);modal.remove();resolve(value);};
  const key=function(e){if(e.key==='Escape'){e.preventDefault();finish(null);}else if(e.key==='Enter'){e.preventDefault();finish(input.value);}};
  modal.querySelector('[data-tp2628-cancel]').onclick=function(){finish(null);};
  modal.querySelector('[data-tp2628-confirm]').onclick=function(){finish(input.value);};
  modal.addEventListener('click',function(e){if(e.target===modal)finish(null);});
  document.addEventListener('keydown',key,true);document.body.appendChild(modal);input.focus();input.select?.();
 });
};

const tp149RestoreDialogBase=restoreText;
restoreText=function(text){
 if(String(text).length>20*1024*1024)throw Error('Maximum 20 MB.');
 let d,desired=null;try{d=validateBackup(JSON.parse(String(text).replace(/^\uFEFF/,'')));const raw=JSON.parse(String(text).replace(/^\uFEFF/,''));if(raw&&Object.hasOwn(TP149_LANGS,raw.language))desired=raw.language;}catch(e){throw e;}
 void tp2628Confirm(tp149T('dialog.restore.message',{workouts:d.history.length,weights:d.weights.length}),{title:tp149T('dialog.restore.title'),confirmText:tp149T('backup.restore'),danger:true}).then(function(ok){
  if(!ok)return;
  const oldConfirm=tp2628Confirm;tp2628Confirm=function(){return Promise.resolve(true);};
  try{tp149RestoreDialogBase(text);if(desired){db.set('language',desired);document.documentElement.lang=rf212Lang();}}
  finally{tp2628Confirm=oldConfirm;}
 });
 return true;
};

