rf215Add=function(){
 const kg=Number(String(document.querySelector('#rf215kg')?.value||'').replace(',','.')),d=document.querySelector('#rf215date')?.value;
 if(!kg||kg<30||kg>300){alert(tp149T('weight.invalid'));return;}
 const w=weights();w.unshift({kg:Math.round(kg*10)/10,date:new Date((d||rf215Date())+'T12:00:00').toISOString()});db.set('weights',w);if(typeof cloudChanged==='function')cloudChanged();rf215WeightScreen();
};
rf215Chart=function(a){
 if(a.length<2)return '<div class="muted" style="padding:24px 0;text-align:center">'+esc(tp149T('weight.none'))+'</div>';
 const W=720,H=240,p=28,v=a.map(function(x){return Number(x.kg);}),mn=Math.min(...v),mx=Math.max(...v),sp=Math.max(1,mx-mn);
 const X=function(i){return p+(W-2*p)*(i/(a.length-1));},Y=function(n){return H-p-(H-2*p)*((n-mn)/sp);};
 const pts=a.map(function(d,i){return X(i)+','+Y(+d.kg);}).join(' ');
 const dots=a.map(function(d,i){return '<circle cx="'+X(i)+'" cy="'+Y(+d.kg)+'" r="5" fill="var(--accent)"><title>'+esc(tp149FormatDate(d.date,{year:'numeric',month:'short',day:'numeric'}))+' • '+esc(tp149FormatNumber(d.kg,{minimumFractionDigits:1,maximumFractionDigits:1}))+' kg</title></circle>';}).join('');
 return '<svg viewBox="0 0 '+W+' '+H+'" width="100%" height="240" role="img" aria-label="'+esc(tp149T('weight.trend'))+'"><polyline fill="none" stroke="var(--accent)" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" points="'+pts+'"/>'+dots+'<text x="32" y="24" fill="currentColor" opacity=".65">'+esc(tp149FormatNumber(mx,{minimumFractionDigits:1,maximumFractionDigits:1}))+' kg</text><text x="32" y="226" fill="currentColor" opacity=".65">'+esc(tp149FormatNumber(mn,{minimumFractionDigits:1,maximumFractionDigits:1}))+' kg</text></svg>';
};
rf215WeightScreen=function(){
 state.tab='health';if(typeof rf225HealthPage!=='undefined')rf225HealthPage='weight';state.healthView=false;
 const a=rf215All(),d=rf215Data(),cur=a.at(-1)?.kg??null,start=a[0]?.kg??null,mn=a.length?Math.min(...a.map(function(x){return +x.kg;})):null,mx=a.length?Math.max(...a.map(function(x){return +x.kg;})):null,diff=cur!=null&&start!=null?Math.round((cur-start)*10)/10:null;
 const kg=function(x){return x==null?'—':tp149FormatNumber(x,{minimumFractionDigits:1,maximumFractionDigits:1})+' kg';};
 const ranges=[['7','weight.range.7'],['30','weight.range.30'],['90','weight.range.90'],['365','weight.range.365'],['all','weight.range.all']];
 const cards=a.length?a.slice().reverse().map(function(x){
  return '<div class="card"><strong>'+esc(kg(Number(x.kg)))+'</strong><div class="small muted">'+esc(tp149FormatDate(x.date,{year:'numeric',month:'long',day:'numeric'}))+'</div><br><button class="btn secondary" onclick="rf215Edit(\''+esc(x.date)+'\')">'+esc(tp149T('common.edit'))+'</button> <button class="btn danger" onclick="rf215Del(\''+esc(x.date)+'\')">'+esc(tp149T('common.delete'))+'</button></div>';
 }).join(''):'<div class="muted">'+esc(tp149T('weight.none'))+'</div>';
 const html='<main><button class="btn secondary" onclick="rf263HealthHub()">← '+esc(tp149T('weight.backHealth'))+'</button><div class="hero"><h1>'+esc(tp149T('weight.title'))+'</h1><div class="muted">'+esc(tp149T('weight.intro'))+'</div></div><div class="card"><h2>'+esc(tp149T('weight.addTitle'))+'</h2><div class="grid2"><label>'+esc(tp149T('weight.label'))+' (kg)<input id="rf215kg" class="field" type="number" step="0.1" min="30" max="300" value="'+esc(cur??'')+'"></label><label>'+esc(tp149T('weight.date'))+'<input id="rf215date" class="field" type="date" value="'+esc(rf215Date())+'"></label></div><br><button class="btn block" onclick="rf215Add()">'+esc(tp149T('common.save'))+'</button></div><div class="grid2"><div class="stat"><small>'+esc(tp149T('weight.current'))+'</small><strong>'+esc(kg(cur))+'</strong></div><div class="stat"><small>'+esc(tp149T('weight.start'))+'</small><strong>'+esc(kg(start))+'</strong></div><div class="stat"><small>'+esc(tp149T('weight.change'))+'</small><strong>'+esc(diff==null?'—':(diff>0?'+':'')+tp149FormatNumber(diff,{minimumFractionDigits:1,maximumFractionDigits:1})+' kg')+'</strong></div><div class="stat"><small>'+esc(tp149T('weight.minMax'))+'</small><strong>'+esc(mn==null?'—':tp149FormatNumber(mn,{minimumFractionDigits:1,maximumFractionDigits:1})+' / '+tp149FormatNumber(mx,{minimumFractionDigits:1,maximumFractionDigits:1})+' kg')+'</strong></div></div><div class="card"><h2>'+esc(tp149T('weight.trend'))+'</h2><div style="display:flex;gap:6px;flex-wrap:wrap">'+ranges.map(function(r){return '<button class="btn '+(rf215Range()===r[0]?'':'secondary')+'" onclick="rf215SetRange(\''+r[0]+'\')">'+esc(tp149T(r[1]))+'</button>';}).join('')+'</div>'+rf215Chart(d)+'</div><div class="section">'+esc(tp149T('weight.history'))+'</div>'+cards+'</main>';
 render(shell(html));
};

