saveSettings=function(){
 const clamp=function(id,fallback){const n=Number(document.getElementById(id)?.value);return Number.isFinite(n)?Math.max(.25,Math.min(10,Math.round(n*4)/4)):fallback;},cur=settings();
 db.set('settings',Object.assign({},cur,{rest:Math.max(30,Math.min(300,Number(document.getElementById('rest')?.value)||cur.rest||90)),progressionSteps:{isolation:clamp('tp140StepIsolation',cur.progressionSteps?.isolation??.5),per_hand:clamp('tp140StepPerHand',cur.progressionSteps?.per_hand??1),single_dumbbell:clamp('tp140StepSingle',cur.progressionSteps?.single_dumbbell??1),total:clamp('tp140StepTotal',cur.progressionSteps?.total??2.5)}}));
 if(typeof cloudChanged==='function')cloudChanged();alert(tp149T('settings.saved'));
};

exportData=async function(){
 try{
  const data=JSON.stringify(makeBackup(),null,2),name='trainpilot-backup-'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';
  if(isNative()){
   const r=await nativeFiles().save({name:name,data:data});if(r.cancelled)return;if(!r.verified)throw Error(tp149T('backup.verifyError'));
   db.set('lastExport',{name:r.name,date:new Date().toISOString(),bytes:r.bytes});
   alert(tp149T('backup.exportDone',{name:r.name,bytes:tp149FormatNumber(r.bytes)}));render();
  }else{
   const b=new Blob([data],{type:'application/json'}),url=URL.createObjectURL(b),link=document.createElement('a');
   link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);
   db.set('lastExport',{name:name,date:new Date().toISOString(),bytes:new Blob([data]).size});alert(tp149T('backup.exportBrowser'));render();
  }
 }catch(e){alert(e?.message||String(e));}
};
chooseImport=async function(){
 if(state.session){alert(tp149T('backup.finishWorkout'));return;}
 if(!isNative()){document.getElementById('importFile')?.click();return;}
 try{const r=await nativeFiles().open();if(!r.cancelled)restoreText(r.data);}
 catch(e){alert(tp149T('backup.restoreFailed')+'\n'+(e?.message||e));}
};
importData=async function(file){
 if(!file)return;
 try{if(file.size>20*1024*1024)throw Error(tp149T('backup.maxSize'));restoreText(await file.text());}
 catch(e){alert(tp149T('backup.invalidFile')+'\n'+(e?.message||e));}
 finally{const input=document.getElementById('importFile');if(input)input.value='';}
};

