 const pName=p?tp149ProgramMeta(p,'name'):tp149T('program.noActive'),nextDay=np?programDay(programById(np.programId),np.dayId):p?programDay(p,next):null,nextProgram=np?programById(np.programId):p;
 const nextText=np?tp149T('home.next',{day:nextProgram&&nextDay?tp149ProgramDayName(nextProgram,nextDay):String(np.dayId||''),date:tp149FormatDateTime(np.start,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}):tp149T('home.nextCycle',{day:nextProgram&&nextDay?tp149ProgramDayName(nextProgram,nextDay):String(next||'')});
