 const onboarding='<div class="card onboarding"><h2>'+esc(tp149T(hasProfile?'home.personalPlanner':'planner.help.title'))+'</h2><p>'+esc(tp149T('home.plannerIntro'))+'</p><button class="btn block" onclick="profileScreen()">'+esc(tp149T(hasProfile?'home.profileNewPlan':'planner.help.cta'))+'</button></div>';
