/* The old bridge rebuilt user-protection lists and sorted the full phrase map for every
 * text node. Prepare those values once per render instead. */
var TP150_I18N_SORTED_KEYS=Object.create(null);
var tp150PreparedTranslate=function tp150PreparedTranslate(input,lang,userValues,map,keys){
 let source=String(input),protectedValues=[];
 for(const value of userValues){
  if(!value||!source.includes(value))continue;
  const token='\uE000TPU'+protectedValues.length+'\uE001';
  source=source.split(value).join(token);protectedValues.push([token,value]);
 }
 let out=source;
 for(const k of keys)if(k&&out.includes(k))out=out.split(k).join(map[k]);
 out=tp149Patterns(out,lang);
 for(const pair of protectedValues)out=out.split(pair[0]).join(pair[1]);
 return out;
};
tp149TranslateDom=function tp149TranslateDom(root=document){
 const lang=rf212Lang();document.documentElement.lang=lang;
 if(lang==='hu'||!root||typeof document.createTreeWalker!=='function'||typeof NodeFilter==='undefined')return;
 const map=tp149Map(lang),keys=TP150_I18N_SORTED_KEYS[lang]||(TP150_I18N_SORTED_KEYS[lang]=Object.keys(map).sort(function(a,b){return b.length-a.length;}));
 const userValues=tp149UserValues(),translate=function(value){return tp150PreparedTranslate(value,lang,userValues,map,keys);};
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
 let node;
 while((node=walker.nextNode())){
  const p=node.parentElement;if(!p||/^(SCRIPT|STYLE|TEXTAREA)$/i.test(p.tagName))continue;
  const old=node.nodeValue;if(!old||!old.trim())continue;
  const translated=translate(old);if(translated!==old)node.nodeValue=translated;
 }
 root.querySelectorAll?.('[aria-label],[title],[placeholder]').forEach(function(el){
  for(const a of ['aria-label','title','placeholder']){const v=el.getAttribute(a);if(v){const t=translate(v);if(t!==v)el.setAttribute(a,t);}}
 });
 const weekdayLabels={en:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],de:['Mo','Di','Mi','Do','Fr','Sa','So'],ro:['Lu','Ma','Mi','Jo','Vi','Sâ','Du']};
 root.querySelectorAll?.('.cal-weekdays span').forEach(function(el,i){if(weekdayLabels[lang]?.[i])el.textContent=weekdayLabels[lang][i];});
 root.querySelectorAll?.('.rf2211-weekdays label').forEach(function(el,i){const label=weekdayLabels[lang]?.[i];if(!label)return;for(const n of [...el.childNodes])if(n.nodeType===3&&n.nodeValue.trim())n.nodeValue=label;});
 const list=typeof exercises==='function'?exercises():[],byName=new Map();
 for(const e of list)if(e&&!e.custom){
  for(const name of [e.hu,e.en,tp149ExerciseName(e,lang)])if(name)byName.set(String(name).trim(),e);
 }
 root.querySelectorAll?.('.exercise,.detail,.tp-library-card').forEach(function(card){
  const name=card.querySelector?.('.ex-name')||card.querySelector?.('h2')||card.querySelector?.('h3'),en=card.querySelector?.('.en');if(!name)return;
  const e=byName.get(String(name.textContent||'').trim())||byName.get(String(en?.textContent||'').trim());
  if(e){name.textContent=tp149ExerciseName(e,lang);if(en)en.hidden=true;}
 });
};

/* Keep the one-time delayed repaint needed for the old boot callback, but do not schedule
 * another Coach replacement on every later Home render. */
var tp150CoachSettledLang='';
render=function(custom){
 const out=tp149HomeCoachRepaintRenderBase.apply(this,arguments),lang=rf212Lang();
 if(state.tab==='home'&&lang!=='hu'&&tp150CoachSettledLang!==lang&&document.querySelector('#rf220CoachCard')){
  tp150CoachSettledLang=lang;setTimeout(tp149RepaintLocalizedHomeCoach,0);
 }
 return out;
};

