var tp151T=function(k){const l=typeof rf212Lang==='function'?rf212Lang():'hu';return TP151_TEXT[l]?.[k]||TP151_TEXT.hu[k]||k};

shell=function(content){
 const active=id=>(state.tab===id||(id==='home'&&(state.tab==='stats'||state.tab==='profile')))?'active':'';
 const nav=[['home','nav.home','⌂'],['plan','nav.workout','◫'],['calendar','nav.calendar','▦'],['programs','nav.programs','▤'],['history','nav.log','≡'],['health','nav.health','♡']];
 const actions='<div class="tp151-top-actions"><button class="tp151-top-icon" aria-label="'+esc(tp151T('coach'))+'" onclick="rf233CoachScreen()">✦</button><button class="tp151-top-icon rf208-settings-btn" aria-label="'+esc(tp151T('settings'))+'" onclick="go(\'settings\')">⚙︎</button></div>';
 const html='<div><div class="top tp151-top"><div class="rf208-brand-row"><div class="brand">TrainPilot</div>'+actions+'</div><div class="tag">'+esc(tp149T('brand.tagline'))+'</div><div class="tabs tabs6 rf208-tabs tp151-nav-dock">'+nav.map(x=>'<button class="tab tp151-nav-item '+active(x[0])+'" onclick="go(\''+x[0]+'\')" aria-label="'+esc(tp149T(x[1]))+'"><span class="tp151-nav-icon">'+x[2]+'</span><span class="tp151-nav-label">'+esc(tp149T(x[1]))+'</span></button>').join('')+'</div></div>'+String(content||'')+(state.session&&state.timer>0?timerHtml():'')+'</div>';
 document.documentElement.lang=rf212Lang();return html.replaceAll('null/100','—').replaceAll('null ms','—');
};

var tp151QuickDefaults=function(id){const e=byId(id),item=tp150QuickExercise(id);if(!e||!item)return null;return {sets:item.sets.length,target:String(e.reps||''),weight:Number(item.sets?.[0]?.weight??e.weight??0),body:e.loadType==='bodyweight',unit:typeof tp149LoadLabel==='function'?tp149LoadLabel(e.loadType):loadLabel(e.loadType)}};
var tp151QuickConfig=function(id){
 const e=byId(id),d=tp151QuickDefaults(id);if(!e||!d)return;state.tab='plan';const adding=typeof tp150IsQuick==='function'&&tp150IsQuick(),name=e.custom?String(e.hu||e.en||e.id):tp149ExerciseName(e);
 const weight=d.body?'':'<label>'+esc(tp151T('weight'))+' <span class="small muted">('+esc(d.unit)+')</span><input id="tp151QuickWeight" class="field" inputmode="decimal" type="number" min="0" step="0.5" value="'+esc(d.weight)+'"></label>';
 render(shell('<main class="tp151-quick-config"><button class="btn secondary" onclick="'+(adding?'renderWorkout()':'tp150QuickPicker()')+'">← '+esc(tp149T('common.back'))+'</button><div class="card tp151-quick-config-card"><span class="badge">'+esc(tp150qwT('quickBadge'))+'</span><h1>'+esc(name)+'</h1><p class="small muted">'+esc(tp151T('previous'))+'</p><div class="tp151-form-grid"><label>'+esc(tp151T('sets'))+'<select id="tp151QuickSets" class="field">'+Array.from({length:10},(_,i)=>i+1).map(n=>'<option value="'+n+'" '+(n===d.sets?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label>'+esc(tp151T('target'))+'<input id="tp151QuickTarget" class="field" value="'+esc(d.target)+'"></label>'+weight+'</div><button class="btn block" onclick="tp151SaveQuick(\''+esc(id)+'\')">'+esc(adding?tp151T('quickAdd'):tp151T('quickStart'))+'</button></div></main>'));
};
var tp151BuildQuick=function(id){const e=byId(id),b=tp150QuickExercise(id);if(!e||!b)return null;const n=Math.max(1,Math.min(10,Number(document.getElementById('tp151QuickSets')?.value)||b.sets.length||3)),target=String(document.getElementById('tp151QuickTarget')?.value||e.reps||'').trim().slice(0,40),raw=document.getElementById('tp151QuickWeight')?.value,w=e.loadType==='bodyweight'?0:Math.max(0,Number(String(raw??b.sets?.[0]?.weight??0).replace(',','.'))||0);b.targetReps=target;b.plannedWeight=w;b.sets=Array.from({length:n},(_,i)=>({set:i+1,weight:w,reps:'',done:false}));return b};
var tp151SaveQuick=async function(id){
 const item=tp151BuildQuick(id);if(!item)return;
 if(typeof tp150IsQuick==='function'&&tp150IsQuick()){const i=state.session.exercises.findIndex(x=>x.id===id);if(i>=0){state.session.exercises[i]=item;state.current=i}else{state.session.exercises.push(item);state.current=state.session.exercises.length-1}persistDraft();renderWorkout();window.scrollTo?.(0,0);return}
 if(!(await tp150QuickConfirmReplace()))return;db.set('draft',null);stopTimer();state.tab='plan';state.workout='quick';state.current=0;state.session={type:'quick',quickWorkout:true,programId:null,programName:tp150qwT('title'),dayId:null,workout:'quick',started:new Date().toISOString(),exercises:[item]};persistDraft();renderWorkout();window.scrollTo?.(0,0);
};
tp150QuickAction=function(id){if(typeof tp150IsQuick==='function'&&tp150IsQuick()){const i=state.session.exercises.findIndex(x=>x.id===id);if(i>=0){state.current=i;renderWorkout();window.scrollTo?.(0,0);return}}return tp151QuickConfig(id)};
tp150StartQuickWorkout=function(id){return tp151QuickConfig(id)};
tp150AddQuickExercise=function(id){return tp151QuickConfig(id)};
const tp151RenderWorkoutBase=renderWorkout;
renderWorkout=function(){const out=tp151RenderWorkoutBase.apply(this,arguments);if(typeof tp150IsQuick==='function'&&tp150IsQuick()){const se=state.session?.exercises?.[state.current];if(se?.targetReps){const m=document.querySelector('main .detail .meta');if(m)m.textContent=tp151T('target')+': '+se.sets.length+' × '+se.targetReps;document.querySelectorAll('main .row input[inputmode="numeric"]').forEach(x=>x.placeholder=se.targetReps)}}return out};

toggleCalendarDay=function(date){state.rf2211CalendarDate=date;state.tp151EditingScheduleId=null;render()};
var tp151DateTitle=d=>new Date(d+'T12:00').toLocaleDateString(typeof rf233Locale==='function'?rf233Locale():'hu-HU',{weekday:'long',year:'numeric',month:'long',day:'numeric'});
var tp151EditCalendarItem=id=>{state.tp151EditingScheduleId=id;render()};
var tp151CancelCalendarEdit=()=>{state.tp151EditingScheduleId=null;render()};
var tp151SaveCalendarItem=function(id){
 const rows=scheduled(),i=rows.findIndex(x=>x.id===id&&!x.cancelled);if(i<0)return;const x=rows[i],day=document.getElementById('tp151ScheduleDay')?.value||x.dayId||x.workout,time=document.getElementById('tp151ScheduleTime')?.value||new Date(x.start).toTimeString().slice(0,5),mins=Math.max(10,Math.min(240,Number(document.getElementById('tp151ScheduleMinutes')?.value)||Math.round((Date.parse(x.end)-Date.parse(x.start))/60000)||45)),date=localDateKey(new Date(x.start));
 try{const st=dateAt(date,time);rows[i]={...x,dayId:day,workout:day,start:st.toISOString(),end:new Date(st.getTime()+mins*60000).toISOString(),updatedAt:Date.now()};db.set('scheduled',rows);state.tp151EditingScheduleId=null;if(typeof cloudChanged==='function')cloudChanged();render()}catch(e){alert(e?.message||'Invalid date')}
};
var tp151ScheduleCard=function(x){
 const p=programById(x.programId||'home-basic'),d=programDay(p,x.dayId||x.workout),done=typeof rf209ScheduleDone==='function'?rf209ScheduleDone(x):false,skipped=x.status==='skipped';
 if(state.tp151EditingScheduleId===x.id){const st=new Date(x.start),mins=Math.max(10,Math.round((Date.parse(x.end)-Date.parse(x.start))/60000)||45);return '<div class="card tp151-calendar-item"><strong>'+esc(p?.name||'Program')+'</strong><div class="tp151-form-grid"><label>'+esc(tp151T('programDay'))+'<select id="tp151ScheduleDay" class="field">'+(p?.days||[]).map(day=>'<option value="'+esc(day.id)+'" '+(day.id===(x.dayId||x.workout)?'selected':'')+'>'+esc(typeof tp149ProgramDayName==='function'?tp149ProgramDayName(p,day):(day.name||day.id))+'</option>').join('')+'</select></label><label>'+esc(tp151T('time'))+'<input id="tp151ScheduleTime" class="field" type="time" value="'+esc(st.toTimeString().slice(0,5))+'"></label><label>'+esc(tp151T('duration'))+'<input id="tp151ScheduleMinutes" class="field" type="number" min="10" max="240" value="'+mins+'"></label></div><div class="tp151-action-row"><button class="btn" onclick="tp151SaveCalendarItem(\''+esc(x.id)+'\')">'+esc(tp151T('save'))+'</button><button class="btn secondary" onclick="tp151CancelCalendarEdit()">'+esc(tp151T('cancel'))+'</button></div></div>'}
 const name=(p?tp149ProgramMeta(p,'name'):(p?.name||'Program'))+' • '+(d?(typeof tp149ProgramDayName==='function'?tp149ProgramDayName(p,d):(d.name||d.id)):(x.dayId||x.workout||''));
 return '<div class="card tp151-calendar-item"><div class="tp151-calendar-copy"><span class="badge">'+esc(done?tp151T('completed'):skipped?tp151T('skipped'):tp151T('planned'))+'</span><strong>'+esc(name)+'</strong><span class="small muted">'+esc(tp149FormatDateTime(x.start))+'</span></div><div class="tp151-action-row">'+(!done?'<button class="btn" onclick="startScheduledById(\''+esc(x.id)+'\')">'+esc(tp151T('start'))+'</button>':'')+'<button class="btn secondary" onclick="tp151EditCalendarItem(\''+esc(x.id)+'\')">'+esc(tp151T('edit'))+'</button><button class="btn secondary" onclick="rf260OpenScheduleMove(\''+esc(x.id)+'\',this)">'+esc(tp151T('move'))+'</button>'+(!done?'<button class="btn secondary" onclick="skipSchedule(\''+esc(x.id)+'\')">'+esc(skipped?tp151T('restore'):tp151T('skip'))+'</button>':'')+'<button class="btn danger" onclick="rf209DeleteSchedule(\''+esc(x.id)+'\')">'+esc(tp151T('del'))+'</button></div></div>';
};
var tp151CalendarDayPanel=function(){
 const date=typeof rf2211Selected==='function'?rf2211Selected():(state.rf2211CalendarDate||'');if(!date)return '<div class="card tp151-day-panel muted">'+esc(tp151T('calendarHint'))+'</div>';
 const items=scheduleOnDate(date).filter(x=>!x.cancelled),logs=history().filter(h=>localDateKey(new Date(h.started))===date),p=activeProgram(),cards=items.map(tp151ScheduleCard).join('');
 const logged=logs.map(h=>'<div class="tp151-logged"><div><span class="badge">'+esc(tp151T('logged'))+'</span><strong>'+esc(typeof tp149HistoryTitle==='function'?tp149HistoryTitle(h):(h.programName||h.workout||'Edzés'))+'</strong><span class="small muted">'+esc(tp149FormatDateTime(h.started))+' • '+esc(sessionDuration(h))+'</span></div><button class="btn secondary" onclick="go(\'history\')">'+esc(tp151T('openLog'))+'</button></div>').join('');
 const add=items.length?'':'<div class="tp151-add-day"><span class="small muted">'+esc(tp151T('add'))+'</span><div class="tp151-action-row">'+(p?.days||[]).map(d=>'<button class="btn secondary" onclick="rf2211AddDay(\''+esc(d.id)+'\')">'+esc(typeof tp149ProgramDayName==='function'?tp149ProgramDayName(p,d):(d.name||d.id))+'</button>').join('')+'</div></div>';
 return '<section class="tp151-day-panel"><div class="tp151-day-title"><h2>'+esc(tp151DateTitle(date))+'</h2></div>'+(!cards&&!logged?'<div class="small muted">'+esc(tp151T('empty'))+'</div>':'')+cards+logged+add+'</section>';
};
calendarScreen=function(){const month=tp149FormatDate(new Date(state.calendarMonth+'-01T12:00'),{year:'numeric',month:'long'}),weekdays=tp149Weekdays();return shell('<main class="tp151-calendar"><div class="tp151-page-head"><div><h1>'+esc(tp151T('calendar'))+'</h1><p class="small muted">'+esc(tp151T('calendarHint'))+'</p></div></div>'+rf2211Planner()+'<section class="tp151-calendar-frame"><div class="calendar-head"><button class="btn secondary" onclick="changeCalendarMonth(-1)">‹</button><strong>'+esc(month)+'</strong><button class="btn secondary" onclick="changeCalendarMonth(1)">›</button></div><div class="cal-weekdays">'+weekdays.map(x=>'<span>'+esc(x)+'</span>').join('')+'</div><div class="calendar-grid">'+calendarGrid()+'</div></section>'+tp151CalendarDayPanel()+'</main>')};

healthSettings=async function(){return healthAction(async p=>{let status={};try{status=await p.getStatus()}catch(_){}const perms=status?.permissions||state.health?.permissions||{},keys=Object.keys(perms).filter(k=>k.startsWith('READ_')),missing=!keys.length||keys.some(k=>perms[k]!==true);if(missing){const q=await p.requestRead();state.health.permissions=q?.permissions||perms;return tp151T('permAsk')}await p.openSettings();return tp151T('permOpen')})};
var tp151HealthNumber=function(v){if(v==null||v==='')return null;const n=Number(v);return Number.isFinite(n)?n:null};
var tp151HeartLine=function(day){const a=tp151HealthNumber(day?.averageHeartRate),n=tp151HealthNumber(day?.minHeartRate),x=tp151HealthNumber(day?.maxHeartRate),s=tp151HealthNumber(day?.heartRateSamples);if(a==null&&n==null&&x==null)return '—';const p=[];if(a!=null)p.push(Math.round(a)+' '+tp151T('avg'));if(n!=null)p.push(Math.round(n)+' '+tp151T('min'));if(x!=null)p.push(Math.round(x)+' '+tp151T('max'));return p.join(' · ')+' bpm'+(s!=null&&s>0?' • '+Math.round(s)+' '+tp151T('samples'):'')};

rf235HealthCoachCard=function(){const t=rf235L();if(typeof rf233CoachPlan!=='function')return '';const p=rf233CoachPlan(),r=p.readiness||{},w=typeof rf234Load==='function'?rf234Load():null,targetTitle=typeof rf233TargetTitle==='function'?rf233TargetTitle(p.target):'',targetSub=typeof rf233TargetSub==='function'?rf233TargetSub(p.target):'';return '<div class="card rf235-health-coach tp151-health-coach" id="rf235HealthCoach"><div class="rf235-coach-head"><div><small>'+esc(t.coach)+'</small><strong>'+tp149FormatNumber(r.score)+'/100</strong></div><span class="badge">'+esc(targetTitle)+'</span></div><div class="tp151-advice"><span>'+esc(tp151T('todayAdvice'))+'</span><strong>'+esc(p.decision?.title||'')+'</strong><p>'+esc(p.decision?.text||'')+'</p></div><div class="small muted">'+esc(rf235TargetName(p.target))+(targetSub?' • '+esc(targetSub):'')+'</div><div class="rf235-coach-signals"><span>'+esc(t.sleep)+' <b>'+esc(rf235FmtSleep(r.sleep))+'</b></span><span>'+esc(t.hrv)+' <b>'+esc(rf235FmtHrv(r.hrv))+'</b></span><span>'+esc(t.steps)+' <b>'+esc(rf235FmtSteps(w?.steps))+'</b></span></div><button class="btn block" onclick="rf233CoachScreen()">'+esc(t.open)+'</button></div>'};

rf263HealthHub=function(){
 state.tab='health';state.healthView=false;if(typeof rf225HealthPage!=='undefined')rf225HealthPage='hub';rf240ApplyLedger();
 const ledger=rf240Ledger(),today=ledger.days?.[rf240DayKey(new Date())]||{},rec=state.health?.recovery||{},w=state.health?.wellness||{},all=typeof rf215All==='function'?rf215All():[],manual=Number(all.at?.(-1)?.kg),hw=w.weightKg==null?null:Number(w.weightKg),shown=Number.isFinite(hw)?hw:(Number.isFinite(manual)?manual:null),source=Number.isFinite(hw)?'Health Connect':Number.isFinite(shown)?tp149T('health.localEntry'):'',busy=!!state.health?.busy,sync=ledger.lastSyncAt?tp149FormatDateTime(ledger.lastSyncAt):tp149T('health.never'),bp=w.bloodPressureSystolic==null||w.bloodPressureDiastolic==null?'—':tp149FormatNumber(Math.round(w.bloodPressureSystolic))+'/'+tp149FormatNumber(Math.round(w.bloodPressureDiastolic))+' mmHg';
 const body='<main class="rf263-health tp151-health"><div class="tp151-page-head"><div><h1>'+esc(tp149T('health.title'))+'</h1><p class="small muted">'+esc(tp151T('healthHint'))+'</p></div></div><div class="card rf263-sync-card tp151-health-sync"><div class="grid2 rf263-sync-actions"><button class="btn block" onclick="rf244UnifiedSync()" '+(busy?'disabled':'')+'>'+esc(tp149T('health.sync'))+'</button><button class="btn secondary block" onclick="healthSettings()" '+(busy?'disabled':'')+'>'+esc(tp151T('permissions'))+'</button></div><span class="small muted">'+esc(tp149T('health.lastSync',{time:sync}))+'</span>'+(state.health?.message?'<span class="small" role="status">'+esc(state.health.message)+'</span>':'')+'</div>'+rf235HealthCoachCard()+'<div class="card tp151-health-card"><h2>'+esc(tp151T('today'))+'</h2><div class="grid2">'+rf244Stat(tp149T('health.sleep'),tp149SleepText(rec.sleepMinutes))+rf244Stat('HRV',rec.hrvRmssdMs==null?'—':tp149FormatNumber(Math.round(rec.hrvRmssdMs))+' ms')+rf244Stat(tp149T('health.steps'),today.steps==null?'—':tp149FormatNumber(Math.round(today.steps)))+rf244Stat(tp149T('health.activeEnergy'),today.activeCalories==null?'—':tp149FormatNumber(Math.round(today.activeCalories))+' kcal')+'</div><div class="tp151-pulse"><span>'+esc(tp151T('pulse'))+'</span><strong>'+esc(tp151HeartLine(today))+'</strong></div></div><div class="card tp151-health-card"><h2>'+esc(tp151T('body'))+'</h2><div class="grid2">'+rf244Stat(tp149T('health.weight'),shown==null?'—':tp149HealthFmt(shown,1,' kg'),source)+rf244Stat(tp149T('health.bodyFat'),w.bodyFatPercent==null?'—':tp149HealthFmt(w.bodyFatPercent,1,' %'))+rf244Stat('SpO₂',w.oxygenSaturationPercent==null?'—':tp149HealthFmt(w.oxygenSaturationPercent,1,' %'))+rf244Stat('VO₂max',w.vo2Max==null?'—':tp149HealthFmt(w.vo2Max,1,''))+'</div><button class="btn secondary block" onclick="rf215WeightScreen()">'+esc(tp151T('weightLog'))+'</button></div><details class="card tp151-details"><summary><strong>'+esc(tp151T('more'))+'</strong></summary><div class="grid2">'+rf244Stat(tp149T('health.bloodPressure'),bp)+rf244Stat(tp149T('health.bloodGlucose'),w.bloodGlucoseMmolL==null?'—':tp149HealthFmt(w.bloodGlucoseMmolL,1,' mmol/L'))+rf244Stat(tp149T('health.respiratoryRate'),w.respiratoryRate==null?'—':tp149HealthFmt(w.respiratoryRate,1,' /min'))+rf244Stat(tp149T('health.distance'),today.distanceMeters==null?'—':tp149HealthFmt(today.distanceMeters/1000,2,' km'))+'</div></details><details class="card tp151-details"><summary><strong>'+esc(tp151T('recovery'))+'</strong></summary>'+rf244RecoveryRows()+'</details>'+rf263DiagHtml()+'</main>';render(shell(body));
};

