 state.tab='health';if(typeof rf225HealthPage!=='undefined')rf225HealthPage='weight';const t=rf215T(),a=rf215All(),d=rf215Data(),cur=a.at(-1)?.kg??null,start=a[0]?.kg??null,mn=a.length?Math.min(...a.map(x=>+x.kg)):null,mx=a.length?Math.max(...a.map(x=>+x.kg)):null,diff=cur!=null&&start!=null?Math.round((cur-start)*10)/10:null;
