editCustomProgram=function(id){
 const p=programById(id);if(!p||p.builtin)return;
 const options=function(selected){return exercises().map(function(e){return '<option value="'+esc(e.id)+'" '+(e.id===selected?'selected':'')+'>'+esc(tp149ExerciseName(e))+'</option>'}).join('')};
 const days=(p.days||[]).map(function(d,di){
  const rows=(d.exercises||[]).map(function(eid,ei){return '<div class="custom-ex-row tp152-custom-row"><select class="field" onchange="customExercise(\''+esc(id)+'\','+di+','+ei+',this.value)">'+options(eid)+'</select><div class="tp152-custom-actions"><button class="btn secondary" '+(ei===0?'disabled':'')+' onclick="moveCustomExercise14(\''+esc(id)+'\','+di+','+ei+',-1)">↑</button><button class="btn secondary" '+(ei===d.exercises.length-1?'disabled':'')+' onclick="moveCustomExercise14(\''+esc(id)+'\','+di+','+ei+',1)">↓</button><button class="btn danger" onclick="removeCustomExercise(\''+esc(id)+'\','+di+','+ei+')">×</button></div></div>'}).join('');
  return '<details class="setting tp152-accordion tp152-custom-day" '+(di===0?'open':'')+'><summary><div><strong>'+esc(tp149ProgramDayName(p,d))+'</strong><div class="small muted">'+esc(tp149Plural('exercise.count',d.exercises?.length||0))+'</div></div><span class="tp152-chevron" aria-hidden="true">⌄</span></summary><div class="tp152-accordion-body"><label>'+esc(tp149T('programEdit.dayName'))+'<input class="field" value="'+esc(d.name)+'" onchange="customDayName(\''+esc(id)+'\','+di+',this.value)"></label>'+rows+'<button class="btn secondary block" onclick="addCustomExercise(\''+esc(id)+'\','+di+')">＋ '+esc(tp152T('add'))+'</button></div></details>';
 }).join('');
 render(shell('<main class="tp152-custom-program"><button class="btn secondary" onclick="go(\'programs\')">← '+esc(tp149T('programEdit.back'))+'</button><div class="hero"><h1>'+esc(tp149ProgramMeta(p,'name'))+'</h1><div class="muted">'+esc(tp149T('programEdit.help'))+'</div></div>'+days+'</main>'));
};

profileScreen=function(){
 state.tab='profile';state.healthView=false;if(typeof rf245CoachVisible!=='undefined')rf245CoachVisible=false;
 const old=state.profilePreview||trainingProfile()||{},p=Object.assign({age:'',height:'',weight:'',goal:'fitness',experience:'beginner',activity:'mixed',minutes:45,location:'home',gear:[],cadence:'alternate',split:'auto',excluded:[],focus:'balanced',avoidAreas:[]},old);
 const mins={};for(let m=20;m<=120;m+=5)mins[String(m)]=tp149FormatNumber(m)+' '+tp149T('unit.minute.short');
 const avoid=Object.keys(TP149_PLANNER_ROWS.area).map(function(k){return '<label class="exclude-row"><input type="checkbox" name="pfAvoidArea" value="'+esc(k)+'" '+((p.avoidAreas||[]).includes(k)?'checked':'')+'>'+esc(tp149PlannerRow('area',k))+'</label>'}).join('');
 const excluded=exercises().map(function(e){return '<label class="exclude-row"><input type="checkbox" name="pfExclude" value="'+esc(e.id)+'" '+((p.excluded||[]).includes(e.id)?'checked':'')+'>'+esc(tp149ExerciseName(e))+'</label>'}).join('');
 const group=function(title,body,open){return '<details class="setting tp152-accordion tp152-profile-group" '+(open?'open':'')+'><summary><strong>'+esc(title)+'</strong><span class="tp152-chevron" aria-hidden="true">⌄</span></summary><div class="tp152-accordion-body">'+body+'</div></details>'};
 const basic='<div class="profile-grid"><label>'+esc(tp149T('planner.age'))+'<input id="pfAge" class="field" type="number" min="18" max="100" value="'+esc(p.age)+'"></label><label>'+esc(tp149T('planner.height'))+'<input id="pfHeight" class="field" type="number" min="100" max="250" value="'+esc(p.height)+'"></label><label>'+esc(tp149T('planner.weight'))+'<input id="pfWeight" class="field" type="number" step="0.1" min="30" max="350" value="'+esc(p.weight)+'"></label></div>';
 const goal=profileSelect('pfGoal',tp149T('planner.goal'),tp149PlannerOptions('goal'),p.goal)+profileSelect('pfExperience',tp149T('planner.experience'),tp149PlannerOptions('experience'),p.experience)+profileSelect('pfActivity',tp149T('planner.activity'),tp149PlannerOptions('activity'),p.activity);
 const schedule=profileSelect('pfMinutes',tp149T('planner.minutes'),mins,String(p.minutes))+profileSelect('pfCadence',tp149T('planner.cadence'),tp149PlannerOptions('cadence'),p.cadence)+profileSelect('pfSplit',tp149T('planner.split'),Object.fromEntries(['auto','full','upperlower','ppl'].map(function(k){return [k,tp149PlannerRow('split',k)]})),p.split)+profileSelect('pfFocus',tp149T('planner.focus'),tp149PlannerOptions('focus'),p.focus||'balanced');
 const limits='<details class="rf148-profile-accordion"><summary>'+esc(tp149T('planner.avoidAreas'))+'</summary><div class="rf148-profile-accordion-body"><p class="small muted">'+esc(tp149T('planner.avoidHelp'))+'</p>'+avoid+'</div></details><details class="rf148-profile-accordion"><summary>'+esc(tp149T('planner.excludeExercises'))+'</summary><div class="rf148-profile-accordion-body">'+excluded+'</div></details>';
 const html='<main class="tp152-profile"><button class="btn secondary" onclick="go(\'home\')">← '+esc(tp149T('planner.back'))+'</button><div class="hero"><h1>'+esc(tp149T('planner.title'))+'</h1><p>'+esc(tp149T('planner.intro'))+'</p></div>'+group(tp152T('profileBasic'),basic,true)+group(tp152T('profileGoal'),goal,false)+group(tp152T('profileGear'),gearForm132(p),false)+group(tp152T('profileSchedule'),schedule,false)+group(tp152T('profileLimits'),limits,true)+'<button class="btn block tp152-profile-build" onclick="previewProfile()">'+esc(tp149T('planner.build'))+'</button></main>';
 render(shell(html));window.scrollTo?.(0,0);if(typeof rf260ScrollState==='function')rf260ScrollState();
};

var tp152HistoryEditorHtml=function(key){
 const ed=rf151Edit();if(!ed||ed.key!==key)return '';const x=ed.workout,opts=exercises().filter(function(e){return !x.exercises.some(function(v){return v.id===e.id})});
 const exercisesHtml=x.exercises.map(function(raw,ei){const e=rf151SetMeta(raw);return '<details class="card tp152-history-ex" open><summary><div><strong>'+esc(e.hu)+'</strong><div class="en">'+esc(e.en||'')+'</div></div><span class="tp152-chevron" aria-hidden="true">⌄</span></summary><div class="tp152-history-ex-body">'+(e.sets||[]).map(function(set,si){return '<div class="row"><div class="num">'+(si+1)+'</div>'+(e.loadType==='bodyweight'?'<span class="small muted">'+esc(tp149T('workout.bodyweight'))+'</span>':'<label class="small">'+esc(tp149LoadLabel(e.loadType))+'<input class="field" inputmode="decimal" value="'+esc(Number(set.weight)||0)+'" oninput="rf151SetValue('+ei+','+si+',\'weight\',this.value)"></label>')+'<label class="small">'+esc(e.repUnit||'ism.')+'<input class="field" inputmode="numeric" value="'+esc(set.reps||'')+'" oninput="rf151SetValue('+ei+','+si+',\'reps\',this.value)"></label><button class="check '+(set.done?'done':'')+'" onclick="rf151ToggleDone('+ei+','+si+')">'+(set.done?'✓':'OK')+'</button><button class="btn secondary" onclick="rf151RemoveSet('+ei+','+si+')">−</button></div>'}).join('')+'<div class="grid2"><button class="btn secondary" onclick="rf151AddSet('+ei+')">＋ '+esc(tp149T('journal.setCount',{done:1,total:1}).replace(/1\/1.*/,''))+'</button><button class="btn danger" onclick="rf151RemoveExercise('+ei+')">'+esc(tp149T('common.delete'))+'</button></div></div></details>'}).join('');
 return '<section class="card tp152-history-editor"><div class="tp152-history-edit-head"><h2>'+esc(tp152T('historyEdit'))+'</h2><button class="btn secondary" onclick="rf151CancelHistoryEdit()">×</button></div><div class="grid2"><label>'+esc(tp149T('dialog.scheduleMove.date'))+' / '+esc(tp149T('calendar.time'))+'<input class="field" id="rf151Start" type="datetime-local" value="'+esc(rf142LocalInputValue(x.started))+'"></label><label>'+esc(tp149T('weight.range.all'))+'<input class="field" id="rf151End" type="datetime-local" value="'+esc(rf142LocalInputValue(x.finished))+'"></label></div><div class="section">'+esc(tp152T('historyExercises'))+'</div>'+exercisesHtml+'<details class="tp152-inline-add"><summary><strong>＋ '+esc(tp152T('historyAdd'))+'</strong><span class="tp152-chevron" aria-hidden="true">⌄</span></summary><div class="tp152-inline-add-body"><select class="field" id="rf151Exercise"><option value="">—</option>'+opts.map(function(e){return '<option value="'+esc(e.id)+'">'+esc(tp149ExerciseName(e))+'</option>'}).join('')+'</select><button class="btn secondary block" onclick="rf151AddExercise()">＋ '+esc(tp152T('historyAdd'))+'</button></div></details><button class="btn block" onclick="rf151SaveHistory(false)">'+esc(tp149T('common.save'))+'</button><button class="btn secondary block" onclick="rf151SaveHistory(true)">'+esc(tp149T('common.refresh'))+'</button></section>';
};
