  '@media(max-width:430px){.tp1481-side-stopwatch .tp1481-side-grid{grid-template-columns:1fr!important}.tp1481-side-stopwatch .tp1481-side-actions{grid-template-columns:minmax(0,1.2fr) minmax(0,1fr)!important}}'
